export type CategoryRecord = {
	id: CategoryId,
	name: string,
	group_name: string,
	built_in: boolean,
};

/**
 *  Error shape crossing the IPC boundary: `code` is the snake_case
 *  `DbError` variant name (stable, matchable by the frontend); `message` is
 *  the `Display` text (never `Debug` — `Debug` text is for logs, not UI).
 */
export type CommandError = {
	code: string,
	message: string,
};

/**
 *  Inventory-wide counts for the dashboard's summary cards. Unit sums
 *  (`available_units`/`reserved_units`/`checked_out_units`) are raw
 *  milli-unit totals summed across every non-archived part regardless of
 *  that part's own `quantity_unit` — a mixed sum of "each"/"meter"/"foot"
 *  stock has no single true unit, so the dashboard renders it as a plain
 *  count rather than claiming a unit suffix that would be wrong for most of
 *  the parts it covers.
 * 
 *  Every count here excludes archived parts (matching `list_parts(false)`
 *  and the search command's default), because archived stock is no longer
 *  part of the "what's in inventory right now" picture the dashboard
 *  answers. `active_project_count` is the one exception: the `projects`
 *  table is still a Phase 4 stub (just `id`/`name`, no status column), so it
 *  counts every project until that lands.
 */
export type DashboardSummary = {
	available_units: number,
	part_count: number,
	reserved_units: number,
	checked_out_units: number,
	low_stock_count: number,
	active_project_count: number,
	metadata_incomplete_count: number,
	unbinned_count: number,
};

/**
 *  Whether DigiKey credentials are configured, plus the sandbox/production
 *  environment currently selected — NEVER the credentials themselves (only
 *  a `bool` and the non-secret environment string cross the IPC boundary).
 *  Lets the enrichment UI explain why the DigiKey provider silently
 *  contributed nothing to a preview, without needing a command that could
 *  leak a secret.
 */
export type DigiKeyStatus = {
	configured: boolean,
	environment: string,
};

/**
 *  Result of `test_digikey_connection`: a fixed, non-secret status line for
 *  the Settings "Test connection" button. `message` is always one of a
 *  small set of fixed strings ("not configured" / "connected" / "rejected
 *  — check credentials and environment" / "network error or timeout") —
 *  NEVER a raw response body, HTTP status detail, or the credential itself;
 *  see `test_digikey_connection_impl`'s mapping.
 */
export type DigiKeyTestResult = {
	ok: boolean,
	environment: string,
	message: string,
};

