export type Discrepancy = {
	part_id: PartId,
	field: string,
	stored: number,
	recomputed: number,
};

/**
 *  The full preview for one part: one `FieldDiff` per candidate whose
 *  proposed value differs from the current value (a candidate that already
 *  matches is omitted — nothing to review), plus the chain's notes and
 *  which providers ran, for a status line.
 */
export type EnrichmentDiff = {
	part_id: PartId,
	diffs: FieldDiff[],
	notes: string[],
	provider_summary: string[],
	/**
	 *  Image URLs the provider chain found for this part (display-only in
	 *  Phase 5d — not attached/downloaded). Deduplicated, first-seen order;
	 *  `run_chain` already deduplicates by URL across the whole chain, but
	 *  [`image_urls`] deduplicates again so this field's guarantee holds
	 *  regardless of how `images` was produced. An empty vec (never a
	 *  missing field) when no provider found any image.
	 */
	images: string[],
};

/**
 *  One proposed field change: the candidate's value alongside the part's
 *  current value and that field's current recorded provenance, so a caller
 *  (a UI diff screen) can decide what to approve without a further query.
 */
export type FieldDiff = {
	key: string,
	current: string | null,
	proposed: string,
	/**  `EnrichSource::as_db_str()` of the candidate that proposed this value. */
	source: string,
	/**  The field's current `field_provenance.source`, if a row exists yet. */
	current_source: string | null,
	requires_review: boolean,
};

/**
 *  Result of `test_github_connection`: a fixed, non-secret status line for
 *  the Settings "Test connection" button. `message` is always one of a
 *  small set of fixed strings ("not configured" / "connected" /
 *  "rejected — check token" / "repo or branch not found" / "network error
 *  or timeout") — NEVER a response body, HTTP status detail, or the token
 *  itself; see `test_github_connection_impl`'s mapping.
 */
export type GitHubTestResult = {
	ok: boolean,
	message: string,
};

export type GroupId = string;

export type GroupRecord = {
	id: GroupId,
	kind: string,
	note: string,
	reversed_group_id: GroupId | null,
	created_at: string,
	transactions: TransactionRecord[],
};

/**
 *  Every field is an optional AND-composed narrowing filter over
 *  `list_history`'s otherwise-unfiltered "every transaction" result.
 *  `date_from`/`date_to` are `YYYY-MM-DD` (compared against
 *  `date(transactions.created_at)`, inclusive on both ends). `project_id`
 *  matches either leg of a transfer (`project_id` OR `to_project_id`) — the
 *  same "either side of the move" semantics `search.rs`'s `project:` filter
 *  uses. `limit`/`offset` page the (already filtered) result; `total` on the
 *  returned `HistoryPage` is the filtered count before paging, for a
 *  pagination control to render against.
 */
export type HistoryFilter = {
	date_from: string | null,
	date_to: string | null,
	txn_type: string | null,
	part_id: PartId | null,
	project_id: ProjectId | null,
	group_id: GroupId | null,
	limit: number,
	offset: number,
};

/**
 *  A page of `list_history` results plus the total row count the filter
 *  matched (independent of `limit`/`offset`), for a pagination control.
 */
export type HistoryPage = {
	rows: HistoryRow[],
	total: number,
};

/**
 *  One ledger transaction plus enough joined context to render a History row
 *  without a further per-row query.
 */
export type HistoryRow = {
	id: TransactionId,
	part_id: PartId,
	display_name: string,
	quantity_unit: QuantityUnit,
	/**
	 *  The part this row's transaction belongs to is currently archived —
	 *  drives the History screen's "restore" affordance without a further
	 *  per-row `get_part` call.
	 */
	part_archived: boolean,
	txn_type: string,
	quantity: Quantity,
	from_state: string | null,
	to_state: string | null,
	project_id: ProjectId | null,
	to_project_id: ProjectId | null,
	/**
	 *  Resolved name of whichever project leg is set (`to_project_id` takes
	 *  priority when both are — a transfer's destination — matching the
	 *  same preference `PartDetailTransactions.tsx` already uses client-side
	 *  for `TransactionRecord`), or `None` when neither leg is set.
	 */
	project_name: string | null,
	note: string,
	group_id: GroupId | null,
	/**
	 *  The owning group's `kind` (e.g. `"receive_batch"`,
	 *  `"reverse:receive_batch"`), or `None` for an ungrouped row — lets the
	 *  History screen label a group header without a further `get_group`
	 *  call per group.
	 */
	group_kind: string | null,
	/**
	 *  The group's TRUE total member count — `COUNT(*)` over every
	 *  transaction sharing this row's `group_id`, independent of
	 *  `HistoryFilter` and paging. A `list_history` caller only ever sees
	 *  whatever subset of a group's members matched the current filter and
	 *  landed on the current page, so a client-side count of "members
	 *  visible right now" can silently understate a group's real size (a
	 *  part/project filter or a pagination boundary can hide the rest). This
	 *  field lets the History screen's group header/reversal confirmation
	 *  show the honest total with zero extra per-group queries. `0` for an
	 *  ungrouped row (`group_id` is `None`), where the question doesn't
	 *  apply.
	 */
	group_total: number,
	reversed_txn_id: TransactionId | null,
	/**
	 *  Set once Phase 5's import tables exist and an import writes it; the
	 *  column already exists on `transactions` (reserved ahead of time, see
	 *  migration 0002's `import_id` comment) but nothing populates it yet,
	 *  so this is always `None` today. Passed through now rather than added
	 *  later so the History screen's "view original import" affordance can
	 *  honestly render "nothing to show" instead of fabricating a link.
	 */
	import_id: string | null,
	created_at: string,
	/**
	 *  The same reversibility rule `reverse_transaction` enforces and
	 *  `dashboard.rs::recent_transactions` already flags with: not a
	 *  reversal itself, not part of a group, not already reversed.
	 */
	reversible: boolean,
};

